// The frontend's view of the engine.
//
// Two implementations: Tauri commands when running in the app, and the
// committed fixture when running in a browser or a test. The fixture is
// generated by `xcal ls --json`, so it cannot drift from what the engine
// actually produces — regenerate it rather than editing it.

import fixture from "./fixture.json";
import type { Conflict, Listing, MountEvent, MountInfo, Transfer } from "./types";

/** A connection spec, as the engine takes it. Never carries a secret. */
export type Spec = Record<string, unknown>;

export interface Backend {
  listDir(path: string): Promise<Listing>;
  /** Connect, report what was found, and disconnect again. */
  testConnection(spec: Spec): Promise<MountInfo>;
  /** Connect and keep it, making it the active mount. */
  mount(spec: Spec): Promise<void>;
  /** Whether a host is answering, for the sidebar's dimmed rows. */
  reachable(host: string, port: number): Promise<boolean>;
  /**
   * Subscribe to mount state changes. Returns an unsubscribe.
   *
   * Pushed rather than polled: a share that drops should be reflected while
   * the user is looking at it, and a timer fast enough for that would be a
   * timer asking every mounted server how it is, forever.
   */
  onMountChanged(handler: (event: MountEvent) => void): () => void;
  /** Whether this machine has a credential store that actually keeps things. */
  keychainAvailable(): Promise<boolean>;
  /**
   * Save a credential for a bookmark.
   *
   * There is deliberately no counterpart that reads one back. The window
   * collects a password once and never sees it again; the engine fetches it
   * from the keychain when it connects.
   */
  saveSecret(account: string, secret: string): Promise<void>;
  /** Forget a credential: the box was unticked, or the bookmark removed. */
  forgetSecret(account: string): Promise<void>;
  /**
   * Reconnect a mount asking for read-write, and report what came back.
   *
   * Resolves even when the server refuses the upgrade — a share that is still
   * read-only is an answer, not an error. Read `writable` off the result.
   */
  remountReadWrite(id: string): Promise<MountInfo>;
  /** Create one directory. Not `mkdir -p`: the parent must exist. */
  mkdir(path: string): Promise<void>;
  /** Rename, refusing to clobber unless `replace` says otherwise. */
  rename(from: string, to: string, replace: boolean): Promise<void>;
  /** Remove a file, or a directory and everything under it. */
  remove(path: string, recursive: boolean): Promise<void>;
  /**
   * Every transfer, oldest first.
   *
   * Read on open and after any gap in the event stream. A broadcast channel
   * drops messages for a slow consumer without saying so, so there has to be
   * a way back to the truth.
   */
  transfers(): Promise<Transfer[]>;
  /** Queue a download of each path into a local folder. */
  enqueueDownloads(paths: string[], destination: string): Promise<string[]>;
  /** Queue an upload of each local path into a share folder. */
  enqueueUploads(paths: string[], destination: string): Promise<string[]>;
  pauseTransfer(id: string): Promise<void>;
  cancelTransfer(id: string): Promise<void>;
  /** Put a paused or failed transfer back in the queue. */
  retryTransfer(id: string): Promise<void>;
  pauseAllTransfers(): Promise<void>;
  clearFinishedTransfers(): Promise<void>;
  /** Where downloads land by default. */
  downloadFolder(): Promise<string>;
  /** Which destinations are taken, and what "Keep both" would call them. */
  checkConflicts(paths: string[], destination: string, upload: boolean): Promise<Conflict[]>;
  /** Subscribe to queue changes. Returns an unsubscribe. */
  onTransferChanged(handler: (transfer: Transfer) => void): () => void;
  /** Accept a host's SSH key, after the user compared its fingerprint. */
  trustHostKey(host: string, port: number): Promise<void>;
  /** Forget a host's keys, so the next connection asks again. */
  forgetHostKey(host: string, port: number): Promise<void>;
}

/** True when running inside the Tauri shell rather than a plain browser. */
function inTauri(): boolean {
  return typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;
}

/** Serves the committed fixture, optionally read-only, with optional latency. */
export function fixtureBackend(
  options: {
    readOnly?: boolean;
    latencyMs?: number;
    /**
     * Makes `mount` fail with a host-key error, so the trust prompt and the
     * changed-key banner can be looked at without an SSH server that happens
     * to be in the right state. The shapes match what the engine serialises.
     */
    hostKey?: "unknown" | "changed";
    /**
     * Replace the listing with this many synthetic rows, for measuring the
     * virtualised list against E8-S2's 100k-row criterion. A real share with
     * 100k files is not something to keep in a fixture.
     */
    rows?: number;
    /**
     * Emit a `reconnecting` mount event shortly after subscribing, so E15-S1's
     * banner can be seen. It goes through the real event stream rather than a
     * fake, because the wiring is the part worth looking at.
     */
    dropped?: boolean;
    /**
     * Seed the queue so E13's panel can be looked at. These are fixed rows,
     * not a simulation — the worker is Rust and does not run in a browser.
     */
    queue?: Transfer[];
  } = {},
): Backend {
  const hostKeyFailure = () => {
    if (options.hostKey === "unknown") {
      return {
        message: "unknown host key for nas.local: ssh-ed25519 SHA256:+DiY3wvvV6TuJJhbpZisF/zLDA0zPMSvHdkr4UvCOqU",
        surface: "trust-prompt",
        transient: false,
        hostKey: {
          host: "nas.local",
          port: 22,
          algorithm: "ssh-ed25519",
          fingerprint: "SHA256:+DiY3wvvV6TuJJhbpZisF/zLDA0zPMSvHdkr4UvCOqU",
        },
      };
    }
    return {
      message: "host key for nas.local has changed",
      surface: "banner",
      transient: false,
      hostKey: {
        host: "nas.local",
        port: 22,
        algorithm: "ssh-ed25519",
        fingerprint: "SHA256:LP3sPjr9WCCFN5calZOKGOUseYRLPfxCiOpn2FVoZ0E",
        expected: "SHA256:+DiY3wvvV6TuJJhbpZisF/zLDA0zPMSvHdkr4UvCOqU",
      },
    };
  };

  return {
    async listDir(path = ""): Promise<Listing> {
      if (options.latencyMs) {
        await new Promise((resolve) => setTimeout(resolve, options.latencyMs));
      }
      const listing = structuredClone(fixture) as Listing;
      if (options.rows) {
        listing.entries = Array.from({ length: options.rows }, (_, index) => ({
          name: `Episode ${index + 1}.mkv`,
          path: `${path}/episode-${index + 1}.mkv`,
          kind: "file" as const,
          size: 1_000_000 + index,
          modifiedMs: Date.UTC(2026, 7, 1) + index * 60_000,
          mode: null,
          linkTarget: null,
          kindLabel: "Matroska Video",
          kindCategory: "video" as const,
          hidden: false,
        }));
        return listing;
      }
      if (path !== "") {
        // The fixture is one directory deep, because it is generated from one
        // `xcal ls`. Subdirectories are synthesised so navigation, breadcrumbs
        // and Back can be exercised in a browser at all — a preview
        // affordance, not a claim about what the engine returns.
        listing.entries = [
          {
            name: "notes.txt",
            path: `${path}/notes.txt`,
            kind: "file",
            size: 2048,
            modifiedMs: Date.UTC(2026, 7, 30, 11, 12),
            mode: null,
            linkTarget: null,
            kindLabel: "Plain Text",
            kindCategory: "text" as const,
            hidden: false,
          },
          {
            name: "archive",
            path: `${path}/archive`,
            kind: "dir",
            size: 0,
            modifiedMs: Date.UTC(2026, 7, 28, 9, 4),
            mode: null,
            linkTarget: null,
            kindLabel: "Folder",
            kindCategory: "folder" as const,
            hidden: false,
          },
        ];
      }
      if (options.readOnly) {
        listing.mount.writable = false;
        listing.mount.reason = "Read-only — export mapped `ro,root_squash`";
        listing.mount.protocolLabel = "NFSv4.2";
        listing.mount.securityLabel = "krb5p";
      }
      return listing;
    },
    // A browser has no engine behind it. Refusing rather than inventing a
    // success keeps the demo honest about what it is.
    async testConnection(): Promise<MountInfo> {
      await new Promise((resolve) => setTimeout(resolve, 250));
      throw new Error("not connected to the engine — run the desktop app");
    },
    async mount(): Promise<void> {
      await new Promise((resolve) => setTimeout(resolve, 250));
      if (options.hostKey) throw hostKeyFailure();
      throw new Error("not connected to the engine — run the desktop app");
    },
    // A browser has no queue and nothing to move it with. Empty rather than
    // invented: a preview showing fake transfers would be a preview of
    // something the app does not do.
    async transfers(): Promise<Transfer[]> {
      return options.queue ?? [];
    },
    async enqueueDownloads(): Promise<string[]> {
      throw new Error("not connected to the engine — run the desktop app");
    },
    async enqueueUploads(): Promise<string[]> {
      throw new Error("not connected to the engine — run the desktop app");
    },
    async pauseTransfer(): Promise<void> {},
    async cancelTransfer(): Promise<void> {},
    async retryTransfer(): Promise<void> {},
    async pauseAllTransfers(): Promise<void> {},
    async clearFinishedTransfers(): Promise<void> {},
    async downloadFolder(): Promise<string> {
      return "~/Downloads";
    },
    async checkConflicts(): Promise<Conflict[]> {
      return [];
    },
    onTransferChanged(): () => void {
      return () => undefined;
    },
    // The preview has no filesystem behind it. Refusing is honest; pretending
    // to succeed would leave the list showing something that is not there.
    async mkdir(): Promise<void> {
      throw new Error("not connected to the engine — run the desktop app");
    },
    async rename(): Promise<void> {
      throw new Error("not connected to the engine — run the desktop app");
    },
    async remove(): Promise<void> {
      throw new Error("not connected to the engine — run the desktop app");
    },
    // Nothing changes state in a browser unless the preview asked for it.
    onMountChanged(handler: (event: MountEvent) => void): () => void {
      if (!options.dropped) return () => undefined;
      const timer = setTimeout(
        () =>
          handler({
            // The demo share's bookmark id, so this passes the same
            // active-mount filter a real event does.
            id: "smb:nas.local:media",
            status: "reconnecting",
            mount: null,
            reason: "nas.local stopped answering",
          }),
        400,
      );
      return () => clearTimeout(timer);
    },
    // A browser cannot open a TCP socket, so it cannot answer this. Claiming
    // "reachable" would dim nothing and claiming "unreachable" would dim
    // everything; assuming reachable is the one that misleads least.
    async reachable(): Promise<boolean> {
      return true;
    },
    // A browser has no OS credential store, and pretending otherwise would
    // offer to save a password into nothing.
    async keychainAvailable(): Promise<boolean> {
      return false;
    },
    async saveSecret(): Promise<void> {
      throw new Error("no keychain in the browser preview");
    },
    async forgetSecret(): Promise<void> {
      // Nothing was ever stored, so forgetting is already true.
    },
    // The preview has no session to remount; `?screen=1b` is a fixed
    // read-only mount rather than one that could be upgraded.
    async remountReadWrite(): Promise<MountInfo> {
      await new Promise((resolve) => setTimeout(resolve, 250));
      throw new Error("not connected to the engine — run the desktop app");
    },
    // A browser cannot run ssh-keyscan, so there is no key to accept. The
    // preview reaches the prompt only through `?screen=trust`, which supplies
    // its own fixed fingerprint.
    async trustHostKey(): Promise<void> {
      throw new Error("no ssh-keyscan in the browser preview");
    },
    async forgetHostKey(): Promise<void> {
      // Nothing was ever trusted.
    },
  };
}

/** Calls the Rust side. File bytes never cross this boundary — only metadata. */
function tauriBackend(): Backend {
  return {
    async listDir(path: string): Promise<Listing> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<Listing>("list_dir", { path });
    },
    async testConnection(spec: Spec): Promise<MountInfo> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<MountInfo>("test_connection", { spec });
    },
    async mount(spec: Spec): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("mount", { spec });
    },
    async reachable(host: string, port: number): Promise<boolean> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<boolean>("reachable", { host, port });
    },
    onMountChanged(handler: (event: MountEvent) => void): () => void {
      // `listen` resolves to the unlisten function, which arrives after this
      // has already returned. Holding it in a closure and calling whatever is
      // there at unsubscribe time keeps the caller's contract synchronous —
      // and covers unsubscribing before the listener finished registering.
      let stop: (() => void) | null = null;
      let cancelled = false;
      void import("@tauri-apps/api/event").then(({ listen }) =>
        listen<MountEvent>("mount://changed", (message) => handler(message.payload)).then(
          (unlisten) => {
            if (cancelled) unlisten();
            else stop = unlisten;
          },
        ),
      );
      return () => {
        cancelled = true;
        stop?.();
      };
    },
    async keychainAvailable(): Promise<boolean> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<boolean>("keychain_available");
    },
    async saveSecret(account: string, secret: string): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("save_secret", { account, secret });
    },
    async forgetSecret(account: string): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("forget_secret", { account });
    },
    async remountReadWrite(id: string): Promise<MountInfo> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<MountInfo>("remount_read_write", { id });
    },
    async mkdir(path: string): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("mkdir", { path });
    },
    async rename(from: string, to: string, replace: boolean): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("rename", { from, to, replace });
    },
    async remove(path: string, recursive: boolean): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("remove", { path, recursive });
    },
    async transfers(): Promise<Transfer[]> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<Transfer[]>("transfers");
    },
    async enqueueDownloads(paths: string[], destination: string): Promise<string[]> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<string[]>("enqueue_downloads", { paths, destination });
    },
    async enqueueUploads(paths: string[], destination: string): Promise<string[]> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<string[]>("enqueue_uploads", { paths, destination });
    },
    async pauseTransfer(id: string): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("pause_transfer", { id });
    },
    async cancelTransfer(id: string): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("cancel_transfer", { id });
    },
    async retryTransfer(id: string): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("retry_transfer", { id });
    },
    async pauseAllTransfers(): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("pause_all_transfers");
    },
    async clearFinishedTransfers(): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("clear_finished_transfers");
    },
    async downloadFolder(): Promise<string> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<string>("download_folder");
    },
    async checkConflicts(
      paths: string[],
      destination: string,
      upload: boolean,
    ): Promise<Conflict[]> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<Conflict[]>("check_conflicts", { paths, destination, upload });
    },
    onTransferChanged(handler: (transfer: Transfer) => void): () => void {
      let stop: (() => void) | null = null;
      let cancelled = false;
      void import("@tauri-apps/api/event").then(({ listen }) =>
        listen<{ transfer: Transfer }>("transfer://progress", (message) =>
          handler(message.payload.transfer),
        ).then((unlisten) => {
          if (cancelled) unlisten();
          else stop = unlisten;
        }),
      );
      return () => {
        cancelled = true;
        stop?.();
      };
    },
    async trustHostKey(host: string, port: number): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("trust_host_key", { host, port });
    },
    async forgetHostKey(host: string, port: number): Promise<void> {
      const { invoke } = await import("@tauri-apps/api/core");
      return invoke<void>("forget_host_key", { host, port });
    },
  };
}

export function defaultBackend(): Backend {
  return inTauri() ? tauriBackend() : fixtureBackend();
}

/**
 * Refuse every write when the mount is not writable, before it is sent.
 *
 * E9-S1 asks that no write command *reaches* the engine on a read-only mount.
 * Gating the buttons is not that: a keyboard shortcut, a drag, or a later
 * caller that forgets can still call the method. So the refusal lives on the
 * seam every write must cross, and the components below it cannot opt out.
 *
 * The engine refuses too, and the server refuses after that. This is the layer
 * that makes the AC's wording literally true, and the two behind it are what
 * make a bug in this one harmless.
 */
export function writeGuarded(inner: Backend, writable: () => boolean): Backend {
  const refuse = (verb: string): never => {
    throw {
      message: `${verb} is not possible on a read-only mount`,
      surface: "banner",
      transient: false,
    };
  };
  return {
    ...inner,
    async mkdir(path: string): Promise<void> {
      if (!writable()) refuse("Creating a folder");
      return inner.mkdir(path);
    },
    async rename(from: string, to: string, replace: boolean): Promise<void> {
      if (!writable()) refuse("Renaming");
      return inner.rename(from, to, replace);
    },
    async remove(path: string, recursive: boolean): Promise<void> {
      if (!writable()) refuse("Deleting");
      return inner.remove(path, recursive);
    },
  };
}
